import type { PlayableGenre } from '@gg/schemas';

/** The genres a player can start from: how the create page pitches them, what their games look like, how they play. */
export interface GenreInfo {
  id: PlayableGenre;
  label: string;
  hint: string;
  /** A frame of the genre's sample game (public/genres, regenerated by `pnpm --filter @gg/web genre-previews`). */
  image: string;
  controls: Array<[keys: string, action: string]>;
  /** Example prompts the create page offers for this genre. */
  examples: string[];
}

const MOVE: [string, string] = ['Arrows / WASD', 'move'];
const PAUSE: [string, string] = ['Esc / P', 'pause'];

