export const GENRE_BY_ID: Readonly<Record<string, GenreInfo>> = Object.fromEntries(GENRES.map((g) => [g.id, g]));

export function genreLabel(id: string): string {
  return GENRE_BY_ID[id]?.label ?? id.replace(/-/g, ' ');
}
